local module = {}

local isStudio = game:GetService("RunService"):IsStudio()

local devUserId = 0

if isStudio then
	-- 等待，以便用户加入服务端
	wait(1)
end

-- 获取开发者id
local function _getDevUserId()
	if game["Run Service"]:IsServer() then
		-- 如果在服务端，认为第一个加入游戏的是开发者
		for k, v in ipairs(game.Players:GetPlayers()) do
			return v.UserId
		end
		-- 有可能没有玩家加入
		return 0
	else
		devUserId = game.Players.LocalPlayer.UserId
	end
end

local devUserId = _getDevUserId()

-- 是否拥有指定配置，路径为 "ReplicatedStorage.__developer.{userId}.{key}"
-- 获取userId: print(game.Players.LocalPlayer.UserId)
module.HasConfig = function(key: string)
	if not isStudio then
		return false
	end
	return _G.wdm.Developer.DeveloperConfiguration.HasConfig(key, devUserId)
end

-- 获取配置值，如果路径不存在，会报错
module.GetConfig = function(key: string)
	if not isStudio then
		error("必须确保运行环境为编辑器")
	end
	return _G.wdm.Developer.DeveloperConfiguration.GetConfig(key, devUserId)
end

-- 监控配置变化
module.WatchConfig = function(key: string, func: (value: any) -> ())
	if not isStudio then
		error("必须确保运行环境为编辑器")
	end
	return _G.wdm.Developer.DeveloperConfiguration.WatchConfig(key, func, devUserId)
end

return module
